/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sp_seed_comprehensive_tickets_v2`()
BEGIN
    DECLARE done_tech INT DEFAULT FALSE;
    DECLARE done_catalog INT DEFAULT FALSE;

    DECLARE v_catalog_id BIGINT;
    DECLARE v_catalog_name VARCHAR(255);
    DECLARE v_device_model_id BIGINT;
    DECLARE v_part_id BIGINT;
    DECLARE v_service_type_code VARCHAR(50);
    DECLARE v_standard_duration INT;
    DECLARE v_price DECIMAL(12, 2);
    DECLARE v_warranty_days INT;

    DECLARE v_tech_id BIGINT;
    DECLARE v_tech2_id BIGINT;
    DECLARE v_rec_id BIGINT;
    DECLARE v_branch_id BIGINT;
    
    DECLARE v_cust_id BIGINT;
    DECLARE v_cust_device_id BIGINT;
    DECLARE v_ticket_id BIGINT;
    DECLARE v_repair_item_id BIGINT;
    DECLARE v_part_usage_id BIGINT;
    DECLARE v_assign_id BIGINT;
    DECLARE v_assign2_id BIGINT;

    DECLARE v_extra_catalog_id BIGINT;
    DECLARE v_extra_catalog_name VARCHAR(255);
    DECLARE v_extra_part_id BIGINT;
    DECLARE v_extra_price DECIMAL(12, 2);
    DECLARE v_extra_warranty INT;
    DECLARE v_extra_service_type VARCHAR(50);

    DECLARE v_ticket_code VARCHAR(50);
    DECLARE v_ticket_counter INT DEFAULT 1;
    DECLARE v_cust_name VARCHAR(100);
    DECLARE v_cust_phone VARCHAR(20);

    DECLARE v_t_receive DATETIME;
    DECLARE v_t_assign DATETIME;
    DECLARE v_t_inspect DATETIME;
    DECLARE v_t_approval DATETIME;
    DECLARE v_t_transfer DATETIME;
    DECLARE v_t_start DATETIME;
    DECLARE v_t_wait DATETIME;
    DECLARE v_t_resume DATETIME;
    DECLARE v_t_finish DATETIME;
    DECLARE v_t_handover DATETIME;

    DECLARE v_actual_minutes INT;
    DECLARE v_scenario_type INT;
    DECLARE v_is_multi_item INT;
    DECLARE v_is_transfer INT;

    DECLARE tech_cursor CURSOR FOR 
        SELECT id FROM users WHERE role = 'TECHNICIAN' ORDER BY id ASC;

    DECLARE catalog_cursor CURSOR FOR 
        SELECT sci.id, sci.name, sci.device_model_id, sci.part_id, 
               st.code AS service_type_code, sci.standard_duration_minutes, 
               COALESCE(sci.configured_price, 550000.00), sci.warranty_days
        FROM service_catalog_items sci
        JOIN service_types st ON sci.service_type_id = st.id
        WHERE sci.status = 'ACTIVE';

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done_tech = TRUE;

    SET SQL_SAFE_UPDATES = 0;

    SELECT id INTO v_rec_id FROM users WHERE role = 'RECEPTIONIST' LIMIT 1;
    IF v_rec_id IS NULL THEN SELECT id INTO v_rec_id FROM users LIMIT 1; END IF;

    SELECT id INTO v_branch_id FROM branches WHERE status = 'ACTIVE' LIMIT 1;
    IF v_branch_id IS NULL THEN SELECT id INTO v_branch_id FROM branches LIMIT 1; END IF;

    OPEN tech_cursor;
    
    tech_loop: LOOP
        FETCH tech_cursor INTO v_tech_id;
        IF done_tech THEN LEAVE tech_loop; END IF;

        SELECT id INTO v_tech2_id FROM users WHERE role = 'TECHNICIAN' AND id != v_tech_id ORDER BY id ASC LIMIT 1;
        IF v_tech2_id IS NULL THEN SET v_tech2_id = v_tech_id; END IF;

        SET done_catalog = FALSE;
        OPEN catalog_cursor;

        catalog_loop: LOOP
            FETCH catalog_cursor INTO v_catalog_id, v_catalog_name, v_device_model_id, v_part_id, 
                                      v_service_type_code, v_standard_duration, v_price, v_warranty_days;
            IF done_catalog THEN LEAVE catalog_loop; END IF;

            IF MOD(v_catalog_id + v_tech_id, 13) != 0 THEN

                SET v_cust_name = ELT(1 + FLOOR(RAND() * 25), 
                    'Nguyễn Văn Minh', 'Trần Thị Mai', 'Lê Hoàng Nam', 'Phạm Đức Anh', 'Vũ Thị Hồng', 
                    'Bùi Văn Hùng', 'Đặng Thảo Linh', 'Đỗ Gia Bảo', 'Hồ Quốc Tuấn', 'Ngô Thanh Hà', 
                    'Dương Tấn Phát', 'Lý Hải Đăng', 'Đoàn Phương Thảo', 'Trịnh Quốc Việt', 'Lương Minh Trí', 
                    'Phan Hoài Nam', 'Võ Thị Yến', 'Trương Minh Tuấn', 'Đinh Văn Hoàng', 'Cao Nhật Minh', 
                    'Huỳnh Tấn Đạt', 'Nguyễn Thị Kim Anh', 'Phạm Hồng Phúc', 'Trần Quốc Bảo', 'Lê Khánh Ngọc'
                );
                SET v_cust_phone = CONCAT('09', LPAD(FLOOR(10000000 + (RAND() * 89999999)), 8, '0'));

                SET v_t_receive = DATE_SUB(NOW(), INTERVAL FLOOR(1 + (RAND() * 28)) DAY);
                SET v_t_receive = DATE_ADD(v_t_receive, INTERVAL FLOOR(8 + (RAND() * 9)) HOUR);
                
                SET v_t_assign  = DATE_ADD(v_t_receive, INTERVAL FLOOR(3 + (RAND() * 8)) MINUTE);
                SET v_t_inspect = DATE_ADD(v_t_assign, INTERVAL FLOOR(4 + (RAND() * 6)) MINUTE);
                
                SET v_scenario_type = FLOOR(1 + (RAND() * 100));
                SET v_is_multi_item = IF(MOD(v_ticket_counter, 11) = 0, 1, 0); 
                SET v_is_transfer   = IF(MOD(v_ticket_counter, 15) = 0, 1, 0); 

                SET v_actual_minutes = GREATEST(15, v_standard_duration + FLOOR(-7 + (RAND() * 23)));

                INSERT INTO customers (full_name, phone, created_at, updated_at)
                VALUES (v_cust_name, v_cust_phone, v_t_receive, v_t_receive)
                ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id);
                SET v_cust_id = LAST_INSERT_ID();

                INSERT INTO customer_devices (customer_id, device_model_id, serial_number, storage, created_at, updated_at)
                VALUES (v_cust_id, v_device_model_id, CONCAT('DNX', UPPER(LEFT(MD5(RAND()), 8))), '128GB', v_t_receive, v_t_receive);
                SET v_cust_device_id = LAST_INSERT_ID();

                SET v_ticket_code = CONCAT('ST-202610-', LPAD(v_ticket_counter, 5, '0'));

                IF v_scenario_type <= 70 THEN
                    SET v_t_approval = DATE_ADD(v_t_inspect, INTERVAL 10 MINUTE);
                    SET v_t_start    = DATE_ADD(v_t_approval, INTERVAL 5 MINUTE);
                    SET v_t_finish   = DATE_ADD(v_t_start, INTERVAL v_actual_minutes MINUTE);
                    SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 12 MINUTE);

                    INSERT INTO service_tickets (
                        ticket_code, status, branch_id, customer_device_id, created_by, inspected_by, handed_over_by,
                        received_at, actual_repair_started_at, actual_repair_completed_at, handed_over_at, paid_at,
                        discount_percent, payment_status, payment_method,
                        customer_reported_issue, inspection_result, estimate_source, estimated_duration_minutes,
                        estimated_start_at, estimated_completion_at, updated_at
                    ) VALUES (
                        v_ticket_code, 'HANDED_OVER', v_branch_id, v_cust_device_id, v_rec_id, v_tech_id, v_rec_id,
                        v_t_receive, v_t_start, v_t_finish, v_t_handover, v_t_handover,
                        0.00, 'PAID', 'BANK_TRANSFER',
                        CONCAT('Kiểm tra và xử lý: ', v_catalog_name),
                        CONCAT('Đã chẩn đoán kỹ thuật, đủ điều kiện thực hiện ', v_catalog_name),
                        'STANDARD', v_standard_duration,
                        v_t_start, DATE_ADD(v_t_start, INTERVAL v_standard_duration MINUTE), v_t_handover
                    );
                    SET v_ticket_id = LAST_INSERT_ID();

                    INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                    (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị tại quầy'),
                    (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công kỹ thuật viên'),
                    (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_tech_id, 'Tháo máy & kiểm tra chẩn đoán'),
                    (v_ticket_id, 'INSPECTING', 'REPAIRING', v_t_start, v_tech_id, 'Bắt đầu sửa chữa'),
                    (v_ticket_id, 'REPAIRING', 'WAITING_HANDOVER', v_t_finish, v_tech_id, 'Hoàn thành sửa chữa'),
                    (v_ticket_id, 'WAITING_HANDOVER', 'HANDED_OVER', v_t_handover, v_rec_id, 'Khách nghiệm thu & thanh toán');

                ELSEIF v_scenario_type <= 85 THEN
                    SET v_t_approval = DATE_ADD(v_t_inspect, INTERVAL 10 MINUTE);
                    SET v_t_start    = DATE_ADD(v_t_approval, INTERVAL 15 MINUTE);
                    SET v_t_finish   = DATE_ADD(v_t_start, INTERVAL v_actual_minutes MINUTE);
                    SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 15 MINUTE);

                    INSERT INTO service_tickets (
                        ticket_code, status, branch_id, customer_device_id, created_by, inspected_by, handed_over_by,
                        received_at, actual_repair_started_at, actual_repair_completed_at, handed_over_at, paid_at,
                        discount_percent, payment_status, payment_method,
                        customer_reported_issue, inspection_result, estimate_source, estimated_duration_minutes,
                        estimated_start_at, estimated_completion_at, updated_at
                    ) VALUES (
                        v_ticket_code, 'HANDED_OVER', v_branch_id, v_cust_device_id, v_rec_id, v_tech_id, v_rec_id,
                        v_t_receive, v_t_start, v_t_finish, v_t_handover, v_t_handover,
                        0.00, 'PAID', 'CASH',
                        CONCAT('Thiết bị gặp sự cố: ', v_catalog_name),
                        CONCAT('Thay đổi phương án sửa chữa, gọi điện tư vấn và chờ khách hàng xác nhận'),
                        'STANDARD', v_standard_duration,
                        v_t_start, DATE_ADD(v_t_start, INTERVAL v_standard_duration MINUTE), v_t_handover
                    );
                    SET v_ticket_id = LAST_INSERT_ID();

                    INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                    (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị'),
                    (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công KTV'),
                    (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_tech_id, 'Tháo máy & kiểm tra'),
                    (v_ticket_id, 'INSPECTING', 'WAITING_APPROVAL', v_t_approval, v_tech_id, 'Thay đổi phương án, gọi điện chờ khách xác nhận'),
                    (v_ticket_id, 'WAITING_APPROVAL', 'REPAIRING', v_t_start, v_tech_id, 'Khách hàng đồng ý phương án, tiếp tục xử lý'),
                    (v_ticket_id, 'REPAIRING', 'WAITING_HANDOVER', v_t_finish, v_tech_id, 'Sửa chữa hoàn tất'),
                    (v_ticket_id, 'WAITING_HANDOVER', 'HANDED_OVER', v_t_handover, v_rec_id, 'Đã bàn giao cho khách');

                ELSE
                    SET v_t_approval = DATE_ADD(v_t_inspect, INTERVAL 8 MINUTE);
                    SET v_t_start    = DATE_ADD(v_t_approval, INTERVAL 5 MINUTE);
                    SET v_t_wait     = DATE_ADD(v_t_start, INTERVAL 10 MINUTE);
                    SET v_t_resume   = DATE_ADD(v_t_wait, INTERVAL 15 MINUTE);
                    SET v_t_finish   = DATE_ADD(v_t_resume, INTERVAL v_actual_minutes MINUTE);
                    SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 10 MINUTE);

                    INSERT INTO service_tickets (
                        ticket_code, status, branch_id, customer_device_id, created_by, inspected_by, handed_over_by,
                        received_at, actual_repair_started_at, actual_repair_completed_at, handed_over_at, paid_at,
                        discount_percent, payment_status, payment_method,
                        customer_reported_issue, inspection_result, estimate_source, estimated_duration_minutes,
                        estimated_start_at, estimated_completion_at, updated_at
                    ) VALUES (
                        v_ticket_code, 'HANDED_OVER', v_branch_id, v_cust_device_id, v_rec_id, v_tech_id, v_rec_id,
                        v_t_receive, v_t_start, v_t_finish, v_t_handover, v_t_handover,
                        0.00, 'PAID', 'BANK_TRANSFER',
                        CONCAT('Yêu cầu xử lý: ', v_catalog_name),
                        CONCAT('Đã chẩn đoán, chờ lấy linh kiện từ kho tổng'),
                        'STANDARD', v_standard_duration,
                        v_t_start, DATE_ADD(v_t_start, INTERVAL v_standard_duration MINUTE), v_t_handover
                    );
                    SET v_ticket_id = LAST_INSERT_ID();

                    INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                    (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị'),
                    (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công KTV'),
                    (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_tech_id, 'Kiểm tra chẩn đoán'),
                    (v_ticket_id, 'INSPECTING', 'REPAIRING', v_t_start, v_tech_id, 'Bắt đầu tháo lắp'),
                    (v_ticket_id, 'REPAIRING', 'WAITING_PART', v_t_wait, v_tech_id, 'Tạm dừng chờ điều chuyển linh kiện'),
                    (v_ticket_id, 'WAITING_PART', 'REPAIRING', v_t_resume, v_tech_id, 'Linh kiện về kho, tiếp tục thay thế'),
                    (v_ticket_id, 'REPAIRING', 'WAITING_HANDOVER', v_t_finish, v_tech_id, 'Hoàn thành sửa chữa'),
                    (v_ticket_id, 'WAITING_HANDOVER', 'HANDED_OVER', v_t_handover, v_rec_id, 'Bàn giao thiết bị');
                END IF;

                IF v_is_transfer = 1 AND v_tech2_id != v_tech_id THEN
                    SET v_t_transfer = DATE_ADD(v_t_start, INTERVAL 15 MINUTE);

                    INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                    VALUES (v_ticket_id, v_tech_id, v_rec_id, v_t_assign, v_t_transfer, 'ENDED', 'MANUAL_OVERRIDE');
                    SET v_assign_id = LAST_INSERT_ID();

                    INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                    VALUES (v_ticket_id, v_tech2_id, v_tech_id, v_t_transfer, v_t_finish, 'ENDED', 'TRANSFER');
                    SET v_assign2_id = LAST_INSERT_ID();

                    INSERT INTO transfers (from_assignment_id, to_assignment_id, reason, transferred_by, transferred_at)
                    VALUES (v_assign_id, v_assign2_id, 'Phát sinh yêu cầu kỹ thuật chuyên sâu, chuyển KTV xử lý', v_tech_id, v_t_transfer);
                ELSE
                    INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                    VALUES (v_ticket_id, v_tech_id, v_rec_id, v_t_assign, v_t_finish, 'ENDED', 'MANUAL_OVERRIDE');
                    SET v_assign_id = LAST_INSERT_ID();
                END IF;

                INSERT INTO repair_items (
                    service_ticket_id, service_catalog_item_id, item_name_snapshot, base_price, final_price, 
                    approval_status, confirmation_method, approval_decision_at, approval_recorded_by,
                    warranty_start_date, warranty_end_date, created_at, updated_at
                ) VALUES (
                    v_ticket_id, v_catalog_id, v_catalog_name, v_price, v_price,
                    'APPROVED', IF(v_scenario_type BETWEEN 71 AND 85, 'PHONE', 'DIRECT'), v_t_approval, v_rec_id,
                    DATE(v_t_handover), DATE_ADD(DATE(v_t_handover), INTERVAL v_warranty_days DAY),
                    v_t_inspect, v_t_handover
                );
                SET v_repair_item_id = LAST_INSERT_ID();

                -- XUẤT KHO USAGE_OUT & TRỪ TỒN KHO THỰC TẾ
                IF v_part_id IS NULL AND v_service_type_code = 'REPLACEMENT' THEN
                    SELECT id INTO v_part_id FROM parts WHERE status = 'ACTIVE' ORDER BY RAND() LIMIT 1;
                END IF;

                IF v_part_id IS NOT NULL THEN
                    INSERT INTO part_usages (repair_item_id, part_id, quantity, used_at, recorded_by, status)
                    VALUES (v_repair_item_id, v_part_id, 1, v_t_start, v_tech_id, 'ACTIVE');
                    SET v_part_usage_id = LAST_INSERT_ID();

                    INSERT INTO inventory_transactions (
                        transaction_type, part_id, part_usage_id, source_branch_id,
                        quantity, recorded_by, created_at, note
                    ) VALUES (
                        'USAGE_OUT', v_part_id, v_part_usage_id, v_branch_id,
                        1, v_tech_id, v_t_start, CONCAT('Xuất linh kiện tự động cho phiếu ', v_ticket_code)
                    );

                    UPDATE branch_inventories 
                    SET quantity = GREATEST(0, quantity - 1),
                        updated_at = v_t_start
                    WHERE branch_id = v_branch_id AND part_id = v_part_id;
                END IF;

                -- MULTI-ITEM (Kèm theo linh kiện / dịch vụ phụ)
                IF v_is_multi_item = 1 THEN
                    SELECT sci.id, sci.name, sci.part_id, COALESCE(sci.configured_price, 350000.00), sci.warranty_days, st.code
                    INTO v_extra_catalog_id, v_extra_catalog_name, v_extra_part_id, v_extra_price, v_extra_warranty, v_extra_service_type
                    FROM service_catalog_items sci
                    JOIN service_types st ON sci.service_type_id = st.id
                    WHERE sci.status = 'ACTIVE' AND sci.id != v_catalog_id
                    ORDER BY RAND() LIMIT 1;

                    IF v_extra_catalog_id IS NOT NULL THEN
                        INSERT INTO repair_items (
                            service_ticket_id, service_catalog_item_id, item_name_snapshot, base_price, final_price, 
                            approval_status, confirmation_method, approval_decision_at, approval_recorded_by,
                            warranty_start_date, warranty_end_date, created_at, updated_at
                        ) VALUES (
                            v_ticket_id, v_extra_catalog_id, CONCAT('Kèm theo: ', v_extra_catalog_name), v_extra_price, v_extra_price,
                            'APPROVED', 'DIRECT', v_t_approval, v_rec_id,
                            DATE(v_t_handover), DATE_ADD(DATE(v_t_handover), INTERVAL v_extra_warranty DAY),
                            v_t_inspect, v_t_handover
                        );
                        SET v_repair_item_id = LAST_INSERT_ID();

                        IF v_extra_part_id IS NULL AND v_extra_service_type = 'REPLACEMENT' THEN
                            SELECT id INTO v_extra_part_id FROM parts WHERE status = 'ACTIVE' ORDER BY RAND() LIMIT 1;
                        END IF;

                        IF v_extra_part_id IS NOT NULL THEN
                            INSERT INTO part_usages (repair_item_id, part_id, quantity, used_at, recorded_by, status)
                            VALUES (v_repair_item_id, v_extra_part_id, 1, v_t_start, v_tech_id, 'ACTIVE');
                            SET v_part_usage_id = LAST_INSERT_ID();

                            INSERT INTO inventory_transactions (
                                transaction_type, part_id, part_usage_id, source_branch_id,
                                quantity, recorded_by, created_at, note
                            ) VALUES (
                                'USAGE_OUT', v_extra_part_id, v_part_usage_id, v_branch_id,
                                1, v_tech_id, v_t_start, CONCAT('Xuất linh kiện phụ cho phiếu ', v_ticket_code)
                            );

                            UPDATE branch_inventories 
                            SET quantity = GREATEST(0, quantity - 1),
                                updated_at = v_t_start
                            WHERE branch_id = v_branch_id AND part_id = v_extra_part_id;
                        END IF;
                    END IF;
                END IF;

                IF MOD(v_ticket_counter, 10) <= 6 THEN
                    INSERT INTO service_feedbacks (service_ticket_id, satisfied, comment, created_at)
                    VALUES (
                        v_ticket_id, 
                        IF(MOD(v_ticket_counter, 8) = 0, 0, 1), 
                        IF(MOD(v_ticket_counter, 8) = 0, 'Sửa hơi lâu một chút nhưng dùng ổn', 'KTV thao tác nhanh, chuyên nghiệp và nhiệt tình'), 
                        DATE_ADD(v_t_handover, INTERVAL FLOOR(10 + (RAND() * 60)) MINUTE)
                    );
                END IF;

                SET v_ticket_counter = v_ticket_counter + 1;
            END IF;

        END LOOP catalog_loop;
        CLOSE catalog_cursor;

    END LOOP tech_loop;
    CLOSE tech_cursor;

    SET SQL_SAFE_UPDATES = 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_seed_comprehensive_tickets_v3` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sp_seed_comprehensive_tickets_v3`()
BEGIN
    DECLARE done_tech INT DEFAULT FALSE;
    DECLARE done_catalog INT DEFAULT FALSE;

    DECLARE v_catalog_id BIGINT;
    DECLARE v_catalog_name VARCHAR(255);
    DECLARE v_device_model_id BIGINT;
    DECLARE v_part_id BIGINT;
    DECLARE v_service_type_code VARCHAR(50);
    DECLARE v_standard_duration INT;
    DECLARE v_price DECIMAL(12, 2);
    DECLARE v_warranty_days INT;

    DECLARE v_tech_id BIGINT;
    DECLARE v_tech2_id BIGINT;
    DECLARE v_rec_id BIGINT;
    DECLARE v_branch_id BIGINT;
    
    DECLARE v_cust_id BIGINT;
    DECLARE v_cust_device_id BIGINT;
    DECLARE v_ticket_id BIGINT;
    DECLARE v_repair_item_id BIGINT;
    DECLARE v_part_usage_id BIGINT;
    DECLARE v_assign_id BIGINT;
    DECLARE v_assign2_id BIGINT;

    DECLARE v_extra_catalog_id BIGINT;
    DECLARE v_extra_catalog_name VARCHAR(255);
    DECLARE v_extra_part_id BIGINT;
    DECLARE v_extra_price DECIMAL(12, 2);
    DECLARE v_extra_warranty INT;
    DECLARE v_extra_service_type VARCHAR(50);

    DECLARE v_ticket_code VARCHAR(50);
    DECLARE v_ticket_counter INT DEFAULT 1;
    DECLARE v_cust_name VARCHAR(100);
    DECLARE v_cust_phone VARCHAR(20);

    DECLARE v_t_receive DATETIME;
    DECLARE v_t_assign DATETIME;
    DECLARE v_t_inspect DATETIME;
    DECLARE v_t_approval DATETIME;
    DECLARE v_t_transfer DATETIME;
    DECLARE v_t_start DATETIME;
    DECLARE v_t_wait DATETIME;
    DECLARE v_t_resume DATETIME;
    DECLARE v_t_finish DATETIME;
    DECLARE v_t_handover DATETIME;

    DECLARE v_actual_minutes INT;
    DECLARE v_scenario_type INT;
    DECLARE v_is_multi_item INT;
    DECLARE v_is_transfer INT;

    -- Con trỏ KTV
    DECLARE tech_cursor CURSOR FOR 
        SELECT id FROM users WHERE role = 'TECHNICIAN' ORDER BY id ASC;

    -- Con trỏ Danh mục dịch vụ
    DECLARE catalog_cursor CURSOR FOR 
        SELECT sci.id, sci.name, sci.device_model_id, sci.part_id, 
               st.code AS service_type_code, sci.standard_duration_minutes, 
               COALESCE(sci.configured_price, 550000.00), sci.warranty_days
        FROM service_catalog_items sci
        JOIN service_types st ON sci.service_type_id = st.id
        WHERE sci.status = 'ACTIVE';

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done_tech = TRUE;

    SET SQL_SAFE_UPDATES = 0;

    SELECT id INTO v_rec_id FROM users WHERE role = 'RECEPTIONIST' LIMIT 1;
    IF v_rec_id IS NULL THEN SELECT id INTO v_rec_id FROM users LIMIT 1; END IF;

    SELECT id INTO v_branch_id FROM branches WHERE status = 'ACTIVE' LIMIT 1;
    IF v_branch_id IS NULL THEN SELECT id INTO v_branch_id FROM branches LIMIT 1; END IF;

    OPEN tech_cursor;
    
    tech_loop: LOOP
        FETCH tech_cursor INTO v_tech_id;
        IF done_tech THEN LEAVE tech_loop; END IF;

        -- Tìm KTV nhận ca chuyển giao
        SELECT id INTO v_tech2_id FROM users WHERE role = 'TECHNICIAN' AND id != v_tech_id ORDER BY id ASC LIMIT 1;
        IF v_tech2_id IS NULL THEN SET v_tech2_id = v_tech_id; END IF;

        SET done_catalog = FALSE;
        OPEN catalog_cursor;

        catalog_loop: LOOP
            FETCH catalog_cursor INTO v_catalog_id, v_catalog_name, v_device_model_id, v_part_id, 
                                      v_service_type_code, v_standard_duration, v_price, v_warranty_days;
            IF done_catalog THEN LEAVE catalog_loop; END IF;

            -- Tạo ngoại lệ: Chừa ngẫu nhiên ~8% dịch vụ không gán cho KTV này
            IF MOD(v_catalog_id + v_tech_id, 13) != 0 THEN

                SET v_cust_name = ELT(1 + FLOOR(RAND() * 25), 
                    'Nguyễn Văn Minh', 'Trần Thị Mai', 'Lê Hoàng Nam', 'Phạm Đức Anh', 'Vũ Thị Hồng', 
                    'Bùi Văn Hùng', 'Đặng Thảo Linh', 'Đỗ Gia Bảo', 'Hồ Quốc Tuấn', 'Ngô Thanh Hà', 
                    'Dương Tấn Phát', 'Lý Hải Đăng', 'Đoàn Phương Thảo', 'Trịnh Quốc Việt', 'Lương Minh Trí', 
                    'Phan Hoài Nam', 'Võ Thị Yến', 'Trương Minh Tuấn', 'Đinh Văn Hoàng', 'Cao Nhật Minh', 
                    'Huỳnh Tấn Đạt', 'Nguyễn Thị Kim Anh', 'Phạm Hồng Phúc', 'Trần Quốc Bảo', 'Lê Khánh Ngọc'
                );
                SET v_cust_phone = CONCAT('09', LPAD(FLOOR(10000000 + (RAND() * 89999999)), 8, '0'));

                -- Rải mốc thời gian trong 28 ngày qua
                SET v_t_receive = DATE_SUB(NOW(), INTERVAL FLOOR(1 + (RAND() * 28)) DAY);
                SET v_t_receive = DATE_ADD(v_t_receive, INTERVAL FLOOR(8 + (RAND() * 9)) HOUR);
                
                SET v_t_assign  = DATE_ADD(v_t_receive, INTERVAL FLOOR(3 + (RAND() * 8)) MINUTE);
                SET v_t_inspect = DATE_ADD(v_t_assign, INTERVAL FLOOR(4 + (RAND() * 6)) MINUTE);
                
                SET v_scenario_type = FLOOR(1 + (RAND() * 100));
                SET v_is_multi_item = IF(MOD(v_ticket_counter, 11) = 0, 1, 0);  -- ~9% ca multi-item
                SET v_is_transfer   = IF(MOD(v_ticket_counter, 15) = 0, 1, 0);  -- ~6.7% ca chuyển KTV

                -- Thời gian thực tế lệch so với chuẩn hệ thống
                SET v_actual_minutes = GREATEST(15, v_standard_duration + FLOOR(-7 + (RAND() * 23)));

                -- Khách hàng & Thiết bị
                INSERT INTO customers (full_name, phone, created_at, updated_at)
                VALUES (v_cust_name, v_cust_phone, v_t_receive, v_t_receive)
                ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id);
                SET v_cust_id = LAST_INSERT_ID();

                INSERT INTO customer_devices (customer_id, device_model_id, serial_number, storage, created_at, updated_at)
                VALUES (v_cust_id, v_device_model_id, CONCAT('DNX', UPPER(LEFT(MD5(RAND()), 8))), '128GB', v_t_receive, v_t_receive);
                SET v_cust_device_id = LAST_INSERT_ID();

                SET v_ticket_code = CONCAT('ST-202610-', LPAD(v_ticket_counter, 5, '0'));

                IF v_scenario_type <= 70 THEN
                    -- KỊCH BẢN 1: CA SỬA THƯỜNG
                    SET v_t_approval = DATE_ADD(v_t_inspect, INTERVAL 10 MINUTE);
                    SET v_t_start    = DATE_ADD(v_t_approval, INTERVAL 5 MINUTE);
                    SET v_t_finish   = DATE_ADD(v_t_start, INTERVAL v_actual_minutes MINUTE);
                    SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 12 MINUTE);

                    INSERT INTO service_tickets (
                        ticket_code, status, branch_id, customer_device_id, created_by, inspected_by, handed_over_by,
                        received_at, actual_repair_started_at, actual_repair_completed_at, handed_over_at, paid_at,
                        discount_percent, payment_status, payment_method,
                        customer_reported_issue, inspection_result, estimate_source, estimated_duration_minutes,
                        estimated_start_at, estimated_completion_at, updated_at
                    ) VALUES (
                        v_ticket_code, 'HANDED_OVER', v_branch_id, v_cust_device_id, v_rec_id, v_tech_id, v_rec_id,
                        v_t_receive, v_t_start, v_t_finish, v_t_handover, v_t_handover,
                        0.00, 'PAID', 'BANK_TRANSFER',
                        CONCAT('Kiểm tra và xử lý: ', v_catalog_name),
                        CONCAT('Đã chẩn đoán kỹ thuật, đủ điều kiện thực hiện ', v_catalog_name),
                        'STANDARD', v_standard_duration,
                        v_t_start, DATE_ADD(v_t_start, INTERVAL v_standard_duration MINUTE), v_t_handover
                    );
                    SET v_ticket_id = LAST_INSERT_ID();

                    INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                    (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị tại quầy'),
                    (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công kỹ thuật viên'),
                    (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_tech_id, 'Tháo máy & kiểm tra chẩn đoán'),
                    (v_ticket_id, 'INSPECTING', 'REPAIRING', v_t_start, v_tech_id, 'Bắt đầu sửa chữa'),
                    (v_ticket_id, 'REPAIRING', 'WAITING_HANDOVER', v_t_finish, v_tech_id, 'Hoàn thành sửa chữa'),
                    (v_ticket_id, 'WAITING_HANDOVER', 'HANDED_OVER', v_t_handover, v_rec_id, 'Khách nghiệm thu & thanh toán');

                ELSEIF v_scenario_type <= 85 THEN
                    -- KỊCH BẢN 2: THAY ĐỔI PHƯƠNG ÁN & CHỜ KHÁCH XÁC NHẬN
                    SET v_t_approval = DATE_ADD(v_t_inspect, INTERVAL 10 MINUTE);
                    SET v_t_start    = DATE_ADD(v_t_approval, INTERVAL 15 MINUTE);
                    SET v_t_finish   = DATE_ADD(v_t_start, INTERVAL v_actual_minutes MINUTE);
                    SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 15 MINUTE);

                    INSERT INTO service_tickets (
                        ticket_code, status, branch_id, customer_device_id, created_by, inspected_by, handed_over_by,
                        received_at, actual_repair_started_at, actual_repair_completed_at, handed_over_at, paid_at,
                        discount_percent, payment_status, payment_method,
                        customer_reported_issue, inspection_result, estimate_source, estimated_duration_minutes,
                        estimated_start_at, estimated_completion_at, updated_at
                    ) VALUES (
                        v_ticket_code, 'HANDED_OVER', v_branch_id, v_cust_device_id, v_rec_id, v_tech_id, v_rec_id,
                        v_t_receive, v_t_start, v_t_finish, v_t_handover, v_t_handover,
                        0.00, 'PAID', 'CASH',
                        CONCAT('Thiết bị gặp sự cố: ', v_catalog_name),
                        CONCAT('Thay đổi phương án sửa chữa, gọi điện tư vấn và chờ khách hàng xác nhận'),
                        'STANDARD', v_standard_duration,
                        v_t_start, DATE_ADD(v_t_start, INTERVAL v_standard_duration MINUTE), v_t_handover
                    );
                    SET v_ticket_id = LAST_INSERT_ID();

                    INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                    (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị'),
                    (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công KTV'),
                    (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_tech_id, 'Tháo máy & kiểm tra'),
                    (v_ticket_id, 'INSPECTING', 'WAITING_APPROVAL', v_t_approval, v_tech_id, 'Thay đổi phương án, gọi điện chờ khách xác nhận'),
                    (v_ticket_id, 'WAITING_APPROVAL', 'REPAIRING', v_t_start, v_tech_id, 'Khách hàng đồng ý phương án, tiếp tục xử lý'),
                    (v_ticket_id, 'REPAIRING', 'WAITING_HANDOVER', v_t_finish, v_tech_id, 'Sửa chữa hoàn tất'),
                    (v_ticket_id, 'WAITING_HANDOVER', 'HANDED_OVER', v_t_handover, v_rec_id, 'Đã bàn giao cho khách');

                ELSE
                    -- KỊCH BẢN 3: TẠM DỪNG CHỜ LINH KIỆN
                    SET v_t_approval = DATE_ADD(v_t_inspect, INTERVAL 8 MINUTE);
                    SET v_t_start    = DATE_ADD(v_t_approval, INTERVAL 5 MINUTE);
                    SET v_t_wait     = DATE_ADD(v_t_start, INTERVAL 10 MINUTE);
                    SET v_t_resume   = DATE_ADD(v_t_wait, INTERVAL 15 MINUTE);
                    SET v_t_finish   = DATE_ADD(v_t_resume, INTERVAL v_actual_minutes MINUTE);
                    SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 10 MINUTE);

                    INSERT INTO service_tickets (
                        ticket_code, status, branch_id, customer_device_id, created_by, inspected_by, handed_over_by,
                        received_at, actual_repair_started_at, actual_repair_completed_at, handed_over_at, paid_at,
                        discount_percent, payment_status, payment_method,
                        customer_reported_issue, inspection_result, estimate_source, estimated_duration_minutes,
                        estimated_start_at, estimated_completion_at, updated_at
                    ) VALUES (
                        v_ticket_code, 'HANDED_OVER', v_branch_id, v_cust_device_id, v_rec_id, v_tech_id, v_rec_id,
                        v_t_receive, v_t_start, v_t_finish, v_t_handover, v_t_handover,
                        0.00, 'PAID', 'BANK_TRANSFER',
                        CONCAT('Yêu cầu xử lý: ', v_catalog_name),
                        CONCAT('Đã chẩn đoán, chờ lấy linh kiện từ kho tổng'),
                        'STANDARD', v_standard_duration,
                        v_t_start, DATE_ADD(v_t_start, INTERVAL v_standard_duration MINUTE), v_t_handover
                    );
                    SET v_ticket_id = LAST_INSERT_ID();

                    INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                    (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị'),
                    (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công KTV'),
                    (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_tech_id, 'Kiểm tra chẩn đoán'),
                    (v_ticket_id, 'INSPECTING', 'REPAIRING', v_t_start, v_tech_id, 'Bắt đầu tháo lắp'),
                    (v_ticket_id, 'REPAIRING', 'WAITING_PART', v_t_wait, v_tech_id, 'Tạm dừng chờ điều chuyển linh kiện'),
                    (v_ticket_id, 'WAITING_PART', 'REPAIRING', v_t_resume, v_tech_id, 'Linh kiện về kho, tiếp tục thay thế'),
                    (v_ticket_id, 'REPAIRING', 'WAITING_HANDOVER', v_t_finish, v_tech_id, 'Hoàn thành sửa chữa'),
                    (v_ticket_id, 'WAITING_HANDOVER', 'HANDED_OVER', v_t_handover, v_rec_id, 'Bàn giao thiết bị');
                END IF;

                -- PHÂN CÔNG VÀ CHUYỂN CA KTV (TRANSFERS)
                IF v_is_transfer = 1 AND v_tech2_id != v_tech_id THEN
                    SET v_t_transfer = DATE_ADD(v_t_start, INTERVAL 15 MINUTE);

                    INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                    VALUES (v_ticket_id, v_tech_id, v_rec_id, v_t_assign, v_t_transfer, 'ENDED', 'MANUAL_OVERRIDE');
                    SET v_assign_id = LAST_INSERT_ID();

                    INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                    VALUES (v_ticket_id, v_tech2_id, v_tech_id, v_t_transfer, v_t_finish, 'ENDED', 'TRANSFER');
                    SET v_assign2_id = LAST_INSERT_ID();

                    INSERT INTO transfers (
                        from_assignment_id, target_technician_id, requested_by, responded_by,
                        mode, status, requested_at, responded_at, note, current_condition, work_done, response_note
                    ) VALUES (
                        v_assign_id, v_tech2_id, v_tech_id, v_tech2_id,
                        'DIRECT', 'ACCEPTED', v_t_transfer, v_t_transfer,
                        'Cần KTV chuyên sâu hỗ trợ kiểm tra linh kiện',
                        'Thiết bị đã tháo máy chẩn đoán',
                        'Đã hoàn thành kiểm tra sơ bộ',
                        'Đồng ý tiếp nhận ca'
                    );
                ELSE
                    INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                    VALUES (v_ticket_id, v_tech_id, v_rec_id, v_t_assign, v_t_finish, 'ENDED', 'MANUAL_OVERRIDE');
                    SET v_assign_id = LAST_INSERT_ID();
                END IF;

                -- HẠNG MỤC SỬA CHỮA CHÍNH
                INSERT INTO repair_items (
                    service_ticket_id, service_catalog_item_id, item_name_snapshot, base_price, final_price, 
                    approval_status, confirmation_method, approval_decision_at, approval_recorded_by,
                    warranty_start_date, warranty_end_date, created_at, updated_at
                ) VALUES (
                    v_ticket_id, v_catalog_id, v_catalog_name, v_price, v_price,
                    'APPROVED', IF(v_scenario_type BETWEEN 71 AND 85, 'PHONE', 'DIRECT'), v_t_approval, v_rec_id,
                    DATE(v_t_handover), DATE_ADD(DATE(v_t_handover), INTERVAL v_warranty_days DAY),
                    v_t_inspect, v_t_handover
                );
                SET v_repair_item_id = LAST_INSERT_ID();

                -- XUẤT KHO USAGE_OUT & TRỪ TỒN KHO TRONG BRANCH_INVENTORIES
                IF v_part_id IS NULL AND v_service_type_code = 'REPLACEMENT' THEN
                    SELECT id INTO v_part_id FROM parts WHERE id BETWEEN 30 AND 94 AND status = 'ACTIVE' ORDER BY RAND() LIMIT 1;
                END IF;

                IF v_part_id IS NOT NULL THEN
                    INSERT INTO part_usages (repair_item_id, part_id, quantity, used_at, recorded_by, status)
                    VALUES (v_repair_item_id, v_part_id, 1, v_t_start, v_tech_id, 'ACTIVE');
                    SET v_part_usage_id = LAST_INSERT_ID();

                    INSERT INTO inventory_transactions (
                        transaction_type, part_id, part_usage_id, source_branch_id,
                        quantity, recorded_by, created_at, note
                    ) VALUES (
                        'USAGE_OUT', v_part_id, v_part_usage_id, v_branch_id,
                        1, v_tech_id, v_t_start, CONCAT('Xuất linh kiện tự động cho phiếu ', v_ticket_code)
                    );

                    UPDATE branch_inventories 
                    SET quantity = GREATEST(0, quantity - 1),
                        updated_at = v_t_start
                    WHERE branch_id = v_branch_id AND part_id = v_part_id;
                END IF;

                -- MULTI-ITEM (HẠNG MỤC PHỤ KÈM THEO)
                IF v_is_multi_item = 1 THEN
                    SELECT sci.id, sci.name, sci.part_id, COALESCE(sci.configured_price, 350000.00), sci.warranty_days, st.code
                    INTO v_extra_catalog_id, v_extra_catalog_name, v_extra_part_id, v_extra_price, v_extra_warranty, v_extra_service_type
                    FROM service_catalog_items sci
                    JOIN service_types st ON sci.service_type_id = st.id
                    WHERE sci.status = 'ACTIVE' AND sci.id != v_catalog_id
                    ORDER BY RAND() LIMIT 1;

                    IF v_extra_catalog_id IS NOT NULL THEN
                        INSERT INTO repair_items (
                            service_ticket_id, service_catalog_item_id, item_name_snapshot, base_price, final_price, 
                            approval_status, confirmation_method, approval_decision_at, approval_recorded_by,
                            warranty_start_date, warranty_end_date, created_at, updated_at
                        ) VALUES (
                            v_ticket_id, v_extra_catalog_id, CONCAT('Kèm theo: ', v_extra_catalog_name), v_extra_price, v_extra_price,
                            'APPROVED', 'DIRECT', v_t_approval, v_rec_id,
                            DATE(v_t_handover), DATE_ADD(DATE(v_t_handover), INTERVAL v_extra_warranty DAY),
                            v_t_inspect, v_t_handover
                        );
                        SET v_repair_item_id = LAST_INSERT_ID();

                        IF v_extra_part_id IS NULL AND v_extra_service_type = 'REPLACEMENT' THEN
                            SELECT id INTO v_extra_part_id FROM parts WHERE id BETWEEN 30 AND 94 AND status = 'ACTIVE' ORDER BY RAND() LIMIT 1;
                        END IF;

                        IF v_extra_part_id IS NOT NULL THEN
                            INSERT INTO part_usages (repair_item_id, part_id, quantity, used_at, recorded_by, status)
                            VALUES (v_repair_item_id, v_extra_part_id, 1, v_t_start, v_tech_id, 'ACTIVE');
                            SET v_part_usage_id = LAST_INSERT_ID();

                            INSERT INTO inventory_transactions (
                                transaction_type, part_id, part_usage_id, source_branch_id,
                                quantity, recorded_by, created_at, note
                            ) VALUES (
                                'USAGE_OUT', v_extra_part_id, v_part_usage_id, v_branch_id,
                                1, v_tech_id, v_t_start, CONCAT('Xuất linh kiện phụ cho phiếu ', v_ticket_code)
                            );

                            UPDATE branch_inventories 
                            SET quantity = GREATEST(0, quantity - 1),
                                updated_at = v_t_start
                            WHERE branch_id = v_branch_id AND part_id = v_extra_part_id;
                        END IF;
                    END IF;
                END IF;

                -- PHẢN HỒI ĐÁNH GIÁ KHÁCH HÀNG
                IF MOD(v_ticket_counter, 10) <= 6 THEN
                    INSERT INTO service_feedbacks (service_ticket_id, satisfied, comment, created_at)
                    VALUES (
                        v_ticket_id, 
                        IF(MOD(v_ticket_counter, 8) = 0, 0, 1), 
                        IF(MOD(v_ticket_counter, 8) = 0, 'Sửa hơi lâu một chút nhưng dùng ổn', 'KTV thao tác nhanh, chuyên nghiệp và nhiệt tình'), 
                        DATE_ADD(v_t_handover, INTERVAL FLOOR(10 + (RAND() * 60)) MINUTE)
                    );
                END IF;

                SET v_ticket_counter = v_ticket_counter + 1;
            END IF;

        END LOOP catalog_loop;
        CLOSE catalog_cursor;

    END LOOP tech_loop;
    CLOSE tech_cursor;

    SET SQL_SAFE_UPDATES = 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_seed_comprehensive_tickets_v7` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sp_seed_comprehensive_tickets_v7`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_pass INT DEFAULT 1;
    
    -- Khai báo biến danh mục chính
    DECLARE v_catalog_id BIGINT;
    DECLARE v_catalog_name VARCHAR(255);
    DECLARE v_device_model_id BIGINT;
    DECLARE v_part_id BIGINT;
    DECLARE v_service_type_code VARCHAR(50);
    DECLARE v_standard_duration INT;
    DECLARE v_price DECIMAL(12, 2);
    DECLARE v_warranty_days INT;
    
    -- Biến lưu danh mục phụ (khi phiếu gộp 2-3 dịch vụ)
    DECLARE v_sub_catalog_id BIGINT;
    DECLARE v_sub_catalog_name VARCHAR(255);
    DECLARE v_sub_part_id BIGINT;
    DECLARE v_sub_price DECIMAL(12, 2);
    DECLARE v_sub_duration INT;
    DECLARE v_sub_warranty INT;
    DECLARE v_has_second_item INT DEFAULT 0;

    -- Biến KTV, Lễ tân & Chi nhánh
    DECLARE v_tech1_id BIGINT DEFAULT NULL;
    DECLARE v_tech2_id BIGINT DEFAULT NULL;
    DECLARE v_tech3_id BIGINT DEFAULT NULL;
    DECLARE v_selected_tech_id BIGINT;
    DECLARE v_branch_id BIGINT;
    DECLARE v_rec_id BIGINT;
    DECLARE v_ktv_speed_factor DECIMAL(4, 2) DEFAULT 1.00;
    
    -- Biến phiếu & khách hàng
    DECLARE v_cust_id BIGINT;
    DECLARE v_cust_device_id BIGINT;
    DECLARE v_ticket_id BIGINT;
    DECLARE v_repair_item_id BIGINT;
    DECLARE v_part_usage_id BIGINT;
    DECLARE v_defective_part_usage_id BIGINT;
    
    DECLARE v_ticket_code VARCHAR(50);
    DECLARE v_ticket_counter INT DEFAULT 1;
    DECLARE v_rand_val INT;
    DECLARE v_cust_name VARCHAR(100);
    DECLARE v_cust_phone VARCHAR(20);
    
    -- Mốc thời gian
    DECLARE v_t_receive DATETIME;
    DECLARE v_t_assign DATETIME;
    DECLARE v_t_inspect DATETIME;
    DECLARE v_t_approval DATETIME;
    DECLARE v_t_start DATETIME;
    DECLARE v_t_finish DATETIME;
    DECLARE v_t_handover DATETIME;
    DECLARE v_total_actual_minutes INT;

    -- Con trỏ quét 100% các hạng mục dịch vụ đang ACTIVE
    DECLARE catalog_cursor CURSOR FOR 
        SELECT sci.id, sci.name, sci.device_model_id, sci.part_id, 
               st.code AS service_type_code, sci.standard_duration_minutes, 
               COALESCE(sci.configured_price, 550000.00), sci.warranty_days
        FROM service_catalog_items sci
        JOIN service_types st ON sci.service_type_id = st.id
        WHERE sci.status = 'ACTIVE';
        
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    SET SQL_SAFE_UPDATES = 0;

    -- Lấy danh sách ID của 3 KTV chính theo thứ tự ID
    SELECT id INTO v_tech1_id FROM users WHERE role = 'TECHNICIAN' ORDER BY id ASC LIMIT 1 OFFSET 0;
    SELECT id INTO v_tech2_id FROM users WHERE role = 'TECHNICIAN' ORDER BY id ASC LIMIT 1 OFFSET 1;
    SELECT id INTO v_tech3_id FROM users WHERE role = 'TECHNICIAN' ORDER BY id ASC LIMIT 1 OFFSET 2;
    
    IF v_tech2_id IS NULL THEN SET v_tech2_id = v_tech1_id; END IF;
    IF v_tech3_id IS NULL THEN SET v_tech3_id = v_tech1_id; END IF;

    -- Lễ tân & Chi nhánh
    SELECT id INTO v_rec_id FROM users WHERE role = 'RECEPTIONIST' LIMIT 1;
    IF v_rec_id IS NULL THEN SELECT id INTO v_rec_id FROM users LIMIT 1; END IF;

    SELECT id INTO v_branch_id FROM branches WHERE status = 'ACTIVE' LIMIT 1;
    IF v_branch_id IS NULL THEN SELECT id INTO v_branch_id FROM branches LIMIT 1; END IF;

    -- ========================================================================
    -- CHẠY 4 VÒNG LẶP CATALOG ĐỂ TẠO TẬP DỮ LIỆU ĐỦ LỚN (~920 PHIẾU CHO 3 KTV)
    -- ========================================================================
    pass_loop: LOOP
        IF v_pass > 4 THEN
            LEAVE pass_loop;
        END IF;

        SET done = FALSE;
        OPEN catalog_cursor;

        read_loop: LOOP
            FETCH catalog_cursor INTO v_catalog_id, v_catalog_name, v_device_model_id, v_part_id, 
                                      v_service_type_code, v_standard_duration, v_price, v_warranty_days;
            IF done THEN LEAVE read_loop; END IF;

            -- PHÂN BỔ BẤT ĐỐI XỨNG THỰC TẾ:
            -- KTV 1 nhận ~46% ca (gồm ca khó), KTV 2 nhận ~37%, KTV 3 nhận ~17% (chỉ ca chuẩn)
            SET v_rand_val = FLOOR(1 + (RAND() * 100));
            
            IF MOD(v_catalog_id, 4) = 0 THEN
                -- Ca khó Mainboard/IC/Camera: Chỉ KTV 1 và KTV 2 làm
                IF v_rand_val <= 60 THEN
                    SET v_selected_tech_id = v_tech1_id;
                    SET v_ktv_speed_factor = 0.90; -- KTV 1 làm nhanh
                ELSE
                    SET v_selected_tech_id = v_tech2_id;
                    SET v_ktv_speed_factor = 1.00;
                END IF;
            ELSE
                -- Ca thay thế chuẩn: Cả 3 KTV cùng làm
                IF v_rand_val <= 46 THEN
                    SET v_selected_tech_id = v_tech1_id;
                    SET v_ktv_speed_factor = 0.90;
                ELSEIF v_rand_val <= 83 THEN
                    SET v_selected_tech_id = v_tech2_id;
                    SET v_ktv_speed_factor = 1.00;
                ELSE
                    SET v_selected_tech_id = v_tech3_id;
                    SET v_ktv_speed_factor = 1.15; -- KTV 3 mới làm lâu hơn chút
                END IF;
            END IF;

            -- GHÉP 2 DỊCH VỤ CÙNG DÒNG MÁY (XÁC SUẤT 20%)
            SET v_has_second_item = 0;
            IF (v_ticket_counter % 5 = 0) THEN
                SELECT sci2.id, sci2.name, sci2.part_id, COALESCE(sci2.configured_price, 450000.00), 
                       sci2.standard_duration_minutes, sci2.warranty_days
                INTO v_sub_catalog_id, v_sub_catalog_name, v_sub_part_id, v_sub_price, v_sub_duration, v_sub_warranty
                FROM service_catalog_items sci2
                WHERE sci2.device_model_id = v_device_model_id 
                  AND sci2.id != v_catalog_id 
                  AND sci2.status = 'ACTIVE'
                LIMIT 1;
                
                IF v_sub_catalog_id IS NOT NULL THEN SET v_has_second_item = 1; END IF;
            END IF;

            -- Sinh Tên & SĐT Khách Hàng thực tế Việt Nam
            SET v_cust_name = ELT(1 + FLOOR(RAND() * 25), 
                'Nguyễn Văn Minh', 'Trần Thị Mai', 'Lê Hoàng Nam', 'Phạm Đức Anh', 'Vũ Thị Hồng', 
                'Bùi Văn Hùng', 'Đặng Thảo Linh', 'Đỗ Gia Bảo', 'Hồ Quốc Tuấn', 'Ngô Thanh Hà', 
                'Dương Tấn Phát', 'Lý Hải Đăng', 'Đoàn Phương Thảo', 'Trịnh Quốc Việt', 'Lương Minh Trí', 
                'Phan Hoài Nam', 'Võ Thị Yến', 'Trương Minh Tuấn', 'Đinh Văn Hoàng', 'Cao Nhật Minh', 
                'Huỳnh Tấn Đạt', 'Nguyễn Thị Kim Anh', 'Phạm Hồng Phúc', 'Trần Quốc Bảo', 'Lê Khánh Ngọc'
            );
            SET v_cust_phone = CONCAT('09', LPAD(FLOOR(10000000 + (RAND() * 89999999)), 8, '0'));

            -- Mốc thời gian rải đều trong 28 ngày qua
            SET v_t_receive = DATE_SUB(NOW(), INTERVAL FLOOR(1 + (RAND() * 28)) DAY);
            SET v_t_receive = DATE_ADD(v_t_receive, INTERVAL FLOOR(8 + (RAND() * 9)) HOUR);
            
            SET v_t_assign  = DATE_ADD(v_t_receive, INTERVAL FLOOR(3 + (RAND() * 8)) MINUTE);
            SET v_t_inspect = DATE_ADD(v_t_assign, INTERVAL FLOOR(4 + (RAND() * 6)) MINUTE);
            
            -- Tính thời gian thực tế = (Thời lượng chuẩn * Hệ số KTV) + Nhiễu (-6 đến +15 phút)
            SET v_total_actual_minutes = ROUND((v_standard_duration + IF(v_has_second_item = 1, v_sub_duration, 0)) * v_ktv_speed_factor) + FLOOR(-6 + (RAND() * 21));
            SET v_total_actual_minutes = GREATEST(15, v_total_actual_minutes);

            -- Tạo Khách hàng & Thiết bị
            INSERT INTO customers (full_name, phone, created_at, updated_at)
            VALUES (v_cust_name, v_cust_phone, v_t_receive, v_t_receive)
            ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id);
            SET v_cust_id = LAST_INSERT_ID();

            INSERT INTO customer_devices (customer_id, device_model_id, serial_number, storage, created_at, updated_at)
            VALUES (v_cust_id, v_device_model_id, CONCAT('DNX', UPPER(LEFT(MD5(RAND()), 8))), '128GB', v_t_receive, v_t_receive);
            SET v_cust_device_id = LAST_INSERT_ID();

            SET v_ticket_code = CONCAT('ST-202610-', LPAD(v_ticket_counter, 5, '0'));

            -- PHÂN BỔ KỊCH BẢN ĐA DẠNG
            IF (v_ticket_counter % 10) IN (1, 2, 3, 4, 5, 6) THEN
                -- ============================================================
                -- KỊCH BẢN 1: CA HOÀN THÀNH VÀ ĐÃ BÀN GIAO MÁY (HANDED_OVER)
                -- ============================================================
                SET v_t_approval = DATE_ADD(v_t_inspect, INTERVAL 5 MINUTE);
                SET v_t_start    = DATE_ADD(v_t_approval, INTERVAL 5 MINUTE);
                SET v_t_finish   = DATE_ADD(v_t_start, INTERVAL v_total_actual_minutes MINUTE);
                SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 12 MINUTE);

                INSERT INTO service_tickets (
                    ticket_code, status, branch_id, customer_device_id, created_by, handed_over_by,
                    received_at, actual_repair_started_at, actual_repair_completed_at, handed_over_at, paid_at,
                    discount_percent, payment_status, payment_method, customer_reported_issue, inspection_result,
                    estimate_source, estimated_duration_minutes, estimated_start_at, estimated_completion_at, updated_at
                ) VALUES (
                    v_ticket_code, 'HANDED_OVER', v_branch_id, v_cust_device_id, v_rec_id, v_rec_id,
                    v_t_receive, v_t_start, v_t_finish, v_t_handover, v_t_handover,
                    0.00, 'PAID', IF(MOD(v_ticket_counter, 2)=0, 'BANK_TRANSFER', 'CASH'),
                    CONCAT('Yêu cầu dịch vụ: ', v_catalog_name, IF(v_has_second_item=1, CONCAT(' & ', v_sub_catalog_name), '')),
                    CONCAT('Đã kiểm tra kỹ thuật, máy đủ điều kiện thực hiện ', v_catalog_name),
                    'STANDARD', v_standard_duration + IF(v_has_second_item=1, v_sub_duration, 0),
                    v_t_start, DATE_ADD(v_t_start, INTERVAL v_standard_duration MINUTE), v_t_handover
                );
                SET v_ticket_id = LAST_INSERT_ID();

                INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị tại quầy'),
                (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công kỹ thuật viên'),
                (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_selected_tech_id, 'Tháo máy & kiểm tra chẩn đoán'),
                (v_ticket_id, 'INSPECTING', 'REPAIRING', v_t_start, v_selected_tech_id, 'Bắt đầu tháo lắp sửa chữa'),
                (v_ticket_id, 'REPAIRING', 'WAITING_HANDOVER', v_t_finish, v_selected_tech_id, 'Hoàn thành sửa chữa, test chức năng ok'),
                (v_ticket_id, 'WAITING_HANDOVER', 'HANDED_OVER', v_t_handover, v_rec_id, 'Khách nghiệm thu & thanh toán');

                INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                VALUES (v_ticket_id, v_selected_tech_id, v_rec_id, v_t_assign, v_t_finish, 'ENDED', 'MANUAL_OVERRIDE');

            ELSEIF (v_ticket_counter % 10) = 7 THEN
                -- ============================================================
                -- KỊCH BẢN 2: CHỜ KHÁCH DUYỆT BỔ SUNG DỊCH VỤ -> KHÁCH ĐỒNG Ý
                -- ============================================================
                SET v_t_approval = DATE_ADD(v_t_inspect, INTERVAL 15 MINUTE);
                SET v_t_start    = DATE_ADD(v_t_approval, INTERVAL 10 MINUTE);
                SET v_t_finish   = DATE_ADD(v_t_start, INTERVAL v_total_actual_minutes MINUTE);
                SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 15 MINUTE);

                INSERT INTO service_tickets (
                    ticket_code, status, branch_id, customer_device_id, created_by, handed_over_by,
                    received_at, actual_repair_started_at, actual_repair_completed_at, handed_over_at, paid_at,
                    discount_percent, payment_status, payment_method, customer_reported_issue, inspection_result,
                    estimate_source, estimated_duration_minutes, updated_at
                ) VALUES (
                    v_ticket_code, 'HANDED_OVER', v_branch_id, v_cust_device_id, v_rec_id, v_rec_id,
                    v_t_receive, v_t_start, v_t_finish, v_t_handover, v_t_handover,
                    0.00, 'PAID', 'CASH',
                    CONCAT('Yêu cầu ban đầu: ', v_catalog_name),
                    CONCAT('Phát sinh thêm lỗi, đã gọi điện tư vấn và được khách đồng ý bổ sung ', IF(v_has_second_item=1, v_sub_catalog_name, 'dịch vụ')),
                    'STANDARD', v_standard_duration, v_t_handover
                );
                SET v_ticket_id = LAST_INSERT_ID();

                INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị'),
                (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công KTV'),
                (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_selected_tech_id, 'Tháo máy chẩn đoán'),
                (v_ticket_id, 'INSPECTING', 'WAITING_APPROVAL', v_t_inspect, v_selected_tech_id, 'Phát sinh phương án mới, gọi điện chờ khách xác nhận'),
                (v_ticket_id, 'WAITING_APPROVAL', 'REPAIRING', v_t_start, v_selected_tech_id, 'Khách đồng ý phương án mới, tiếp tục tháo lắp'),
                (v_ticket_id, 'REPAIRING', 'WAITING_HANDOVER', v_t_finish, v_selected_tech_id, 'Hoàn thành sửa chữa'),
                (v_ticket_id, 'WAITING_HANDOVER', 'HANDED_OVER', v_t_handover, v_rec_id, 'Bàn giao máy');

                INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                VALUES (v_ticket_id, v_selected_tech_id, v_rec_id, v_t_assign, v_t_finish, 'ENDED', 'MANUAL_OVERRIDE');

            ELSEIF (v_ticket_counter % 10) = 8 THEN
                -- ============================================================
                -- KỊCH BẢN 3: BÁO LỖI LINH KIỆN (ĐẨY VÀO DEFECTIVE_PART_RETURNS)
                -- ============================================================
                SET v_t_start    = DATE_ADD(v_t_inspect, INTERVAL 5 MINUTE);
                SET v_t_finish   = DATE_ADD(v_t_start, INTERVAL (v_total_actual_minutes + 20) MINUTE);
                SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 10 MINUTE);

                INSERT INTO service_tickets (
                    ticket_code, status, branch_id, customer_device_id, created_by, handed_over_by,
                    received_at, actual_repair_started_at, actual_repair_completed_at, handed_over_at, paid_at,
                    discount_percent, payment_status, payment_method, customer_reported_issue, inspection_result,
                    estimate_source, estimated_duration_minutes, updated_at
                ) VALUES (
                    v_ticket_code, 'HANDED_OVER', v_branch_id, v_cust_device_id, v_rec_id, v_rec_id,
                    v_t_receive, v_t_start, v_t_finish, v_t_handover, v_t_handover,
                    0.00, 'PAID', 'BANK_TRANSFER', CONCAT('Thay thế: ', v_catalog_name),
                    'Linh kiện xuất đợt 1 bị phồng/lỗi nguồn, đã lập biên bản thu hồi kho lỗi và xuất linh kiện mới',
                    'STANDARD', v_standard_duration, v_t_handover
                );
                SET v_ticket_id = LAST_INSERT_ID();

                INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị'),
                (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công KTV'),
                (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_selected_tech_id, 'Kiểm tra chẩn đoán'),
                (v_ticket_id, 'INSPECTING', 'REPAIRING', v_t_start, v_selected_tech_id, 'Bắt đầu tháo máy'),
                (v_ticket_id, 'REPAIRING', 'WAITING_HANDOVER', v_t_finish, v_selected_tech_id, 'Đã hoàn tất đổi linh kiện chuẩn'),
                (v_ticket_id, 'WAITING_HANDOVER', 'HANDED_OVER', v_t_handover, v_rec_id, 'Bàn giao cho khách');

                INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                VALUES (v_ticket_id, v_selected_tech_id, v_rec_id, v_t_assign, v_t_finish, 'ENDED', 'MANUAL_OVERRIDE');

            ELSEIF (v_ticket_counter % 10) = 9 THEN
                -- ============================================================
                -- KỊCH BẢN 4: HỦY CA & ĐÃ BÀN GIAO MÁY TRẢ KHÁCH (CANCELLED + handed_over_at)
                -- ============================================================
                SET v_t_finish   = DATE_ADD(v_t_inspect, INTERVAL 10 MINUTE);
                SET v_t_handover = DATE_ADD(v_t_finish, INTERVAL 15 MINUTE);

                INSERT INTO service_tickets (
                    ticket_code, status, branch_id, customer_device_id, created_by, handed_over_by,
                    received_at, handed_over_at, discount_percent, payment_status, customer_reported_issue,
                    inspection_result, cancel_reason, estimate_source, estimated_duration_minutes, updated_at
                ) VALUES (
                    v_ticket_code, 'CANCELLED', v_branch_id, v_cust_device_id, v_rec_id, v_rec_id,
                    v_t_receive, v_t_handover, 0.00, 'PENDING', CONCAT('Yêu cầu xử lý: ', v_catalog_name),
                    'Khách không đồng ý chi phí phương án phát sinh', 'Khách hủy ca do đổi ý',
                    'STANDARD', v_standard_duration, v_t_handover
                );
                SET v_ticket_id = LAST_INSERT_ID();

                INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị'),
                (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công KTV'),
                (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_selected_tech_id, 'Kiểm tra chẩn đoán'),
                (v_ticket_id, 'INSPECTING', 'CANCELLED', v_t_finish, v_selected_tech_id, 'Hủy ca: Khách không đồng ý báo giá'),
                (v_ticket_id, 'CANCELLED', 'CANCELLED', v_t_handover, v_rec_id, 'Lễ tân đã bàn giao trả lại thiết bị nguyên trạng cho khách');

                INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                VALUES (v_ticket_id, v_selected_tech_id, v_rec_id, v_t_assign, v_t_finish, 'ENDED', 'MANUAL_OVERRIDE');

            ELSE
                -- ============================================================
                -- KỊCH BẢN 5: HỦY CA & CHỜ LỄ TÂN TRẢ MÁY (handed_over_at IS NULL)
                -- ============================================================
                SET v_t_finish = DATE_ADD(v_t_inspect, INTERVAL 8 MINUTE);

                INSERT INTO service_tickets (
                    ticket_code, status, branch_id, customer_device_id, created_by,
                    received_at, discount_percent, payment_status, customer_reported_issue,
                    inspection_result, cancel_reason, estimate_source, estimated_duration_minutes, updated_at
                ) VALUES (
                    v_ticket_code, 'CANCELLED', v_branch_id, v_cust_device_id, v_rec_id,
                    v_t_receive, 0.00, 'PENDING', CONCAT('Yêu cầu xử lý: ', v_catalog_name),
                    'Thiết bị nứt mainboard nặng, KTV tư vấn không nên sửa', 'Máy hỏng nặng không thể phục hồi',
                    'STANDARD', v_standard_duration, v_t_finish
                );
                SET v_ticket_id = LAST_INSERT_ID();

                INSERT INTO service_status_histories (service_ticket_id, from_status, to_status, changed_at, changed_by, note) VALUES
                (v_ticket_id, NULL, 'WAITING_ASSIGNMENT', v_t_receive, v_rec_id, 'Tiếp nhận thiết bị'),
                (v_ticket_id, 'WAITING_ASSIGNMENT', 'ASSIGNED', v_t_assign, v_rec_id, 'Phân công KTV'),
                (v_ticket_id, 'ASSIGNED', 'INSPECTING', v_t_inspect, v_selected_tech_id, 'Kiểm tra chẩn đoán'),
                (v_ticket_id, 'INSPECTING', 'CANCELLED', v_t_finish, v_selected_tech_id, 'Hủy ca: Mainboard bị nứt hỏng nặng. Chờ khách đến nhận lại máy.');

                INSERT INTO assignments (service_ticket_id, technician_id, assigned_by, assigned_at, ended_at, status, source)
                VALUES (v_ticket_id, v_selected_tech_id, v_rec_id, v_t_assign, v_t_finish, 'ENDED', 'MANUAL_OVERRIDE');

            END IF;

            -- CHÈN HẠNG MỤC SỬA CHỮA (REPAIR ITEMS)
            INSERT INTO repair_items (
                service_ticket_id, service_catalog_item_id, item_name_snapshot, base_price, final_price, 
                approval_status, confirmation_method, approval_decision_at, approval_recorded_by,
                warranty_start_date, warranty_end_date, created_at, updated_at
            ) VALUES (
                v_ticket_id, v_catalog_id, v_catalog_name, v_price, v_price,
                IF((v_ticket_counter % 10) IN (9, 0), 'REJECTED', 'APPROVED'), 'DIRECT', v_t_inspect, v_rec_id,
                IF((v_ticket_counter % 10) IN (1,2,3,4,5,6,7,8), DATE(v_t_handover), NULL),
                IF((v_ticket_counter % 10) IN (1,2,3,4,5,6,7,8), DATE_ADD(DATE(v_t_handover), INTERVAL v_warranty_days DAY), NULL),
                v_t_inspect, COALESCE(v_t_handover, NOW())
            );
            SET v_repair_item_id = LAST_INSERT_ID();

            IF v_has_second_item = 1 THEN
                INSERT INTO repair_items (
                    service_ticket_id, service_catalog_item_id, item_name_snapshot, base_price, final_price, 
                    approval_status, confirmation_method, approval_decision_at, approval_recorded_by,
                    warranty_start_date, warranty_end_date, created_at, updated_at
                ) VALUES (
                    v_ticket_id, v_sub_catalog_id, v_sub_catalog_name, v_sub_price, v_sub_price,
                    IF((v_ticket_counter % 10) IN (9, 0), 'REJECTED', 'APPROVED'), 'PHONE', v_t_inspect, v_rec_id,
                    IF((v_ticket_counter % 10) IN (1,2,3,4,5,6,7,8), DATE(v_t_handover), NULL),
                    IF((v_ticket_counter % 10) IN (1,2,3,4,5,6,7,8), DATE_ADD(DATE(v_t_handover), INTERVAL v_sub_warranty DAY), NULL),
                    v_t_inspect, COALESCE(v_t_handover, NOW())
                );
            END IF;

            -- XỬ LÝ LINH KIỆN VÀ KHO HỎNG
            IF (v_ticket_counter % 10) IN (1, 2, 3, 4, 5, 6, 7) AND (v_part_id IS NOT NULL OR v_service_type_code = 'REPLACEMENT') THEN
                IF v_part_id IS NULL THEN
                    SELECT id INTO v_part_id FROM parts WHERE status = 'ACTIVE' LIMIT 1;
                END IF;

                IF v_part_id IS NOT NULL THEN
                    INSERT INTO part_usages (repair_item_id, part_id, quantity, used_at, recorded_by, status)
                    VALUES (v_repair_item_id, v_part_id, 1, v_t_start, v_selected_tech_id, 'ACTIVE');
                    SET v_part_usage_id = LAST_INSERT_ID();

                    INSERT INTO inventory_transactions (
                        transaction_type, part_id, part_usage_id, source_branch_id, quantity, recorded_by, created_at, note
                    ) VALUES (
                        'USAGE_OUT', v_part_id, v_part_usage_id, v_branch_id, 1, v_selected_tech_id, v_t_start, CONCAT('Xuất linh kiện cho phiếu ', v_ticket_code)
                    );

                    UPDATE branch_inventories SET quantity = GREATEST(0, quantity - 1), updated_at = v_t_start
                    WHERE branch_id = v_branch_id AND part_id = v_part_id;
                END IF;

            ELSEIF (v_ticket_counter % 10) = 8 AND v_part_id IS NOT NULL THEN
                -- Pin 1 Lỗi
                INSERT INTO part_usages (repair_item_id, part_id, quantity, used_at, recorded_by, status, defective_return_note)
                VALUES (v_repair_item_id, v_part_id, 1, v_t_start, v_selected_tech_id, 'REVERSED', 'Linh kiện đợt 1 bị phồng rộp, chập nguồn không nhận điện');
                SET v_defective_part_usage_id = LAST_INSERT_ID();

                -- [FIXED] Đã bổ sung cột quantity = 1
                INSERT INTO defective_part_returns (
                    branch_id, source_part_usage_id, quantity, recorded_by, received_at, status, reason, note
                ) VALUES (
                    v_branch_id, v_defective_part_usage_id, 1, v_selected_tech_id, v_t_start, 'IN_STOCK',
                    'LINH_KIEN_LOI_NSX', CONCAT('Hoàn trả linh kiện lỗi từ ca sửa phiếu ', v_ticket_code)
                );

                -- Pin 2 Chuẩn
                INSERT INTO part_usages (repair_item_id, part_id, quantity, used_at, recorded_by, status)
                VALUES (v_repair_item_id, v_part_id, 1, DATE_ADD(v_t_start, INTERVAL 12 MINUTE), v_selected_tech_id, 'ACTIVE');
                SET v_part_usage_id = LAST_INSERT_ID();

                INSERT INTO inventory_transactions (
                    transaction_type, part_id, part_usage_id, source_branch_id, quantity, recorded_by, created_at, note
                ) VALUES (
                    'USAGE_OUT', v_part_id, v_part_usage_id, v_branch_id, 2, v_selected_tech_id, v_t_start, CONCAT('Xuất lại linh kiện đợt 2 cho phiếu ', v_ticket_code)
                );

                UPDATE branch_inventories SET quantity = GREATEST(0, quantity - 2), updated_at = v_t_start
                WHERE branch_id = v_branch_id AND part_id = v_part_id;
            END IF;

            -- ĐÁNH GIÁ PHẢN HỒI KHÁCH HÀNG
            IF (v_ticket_counter % 10) IN (1, 2, 7) THEN
                INSERT INTO service_feedbacks (service_ticket_id, satisfied, comment, created_at)
                VALUES (
                    v_ticket_id, 1, 'Kỹ thuật viên thao tác minh bạch, tư vấn nhiệt tình và xử lý rất cẩn thận',
                    DATE_ADD(v_t_handover, INTERVAL 30 MINUTE)
                );
            END IF;

            SET v_ticket_counter = v_ticket_counter + 1;

        END LOOP;

        CLOSE catalog_cursor;
        SET v_pass = v_pass + 1;
    END LOOP;

    -- ========================================================================
    -- PHẦN 3: TẠO CÁC CA ĐANG MỞ (ACTIVE WORKBENCH) CHO CẢ 3 KTV ĐỂ TEST GIAO DIỆN
    -- ========================================================================
    
    SELECT id, device_model_id INTO v_catalog_id, v_device_model_id FROM service_catalog_items WHERE status = 'ACTIVE' LIMIT 1;

    -- 1. CA ĐANG SỬA CHỮA (REPAIRING) CHO KTV 1
    SET v_ticket_code = CONCAT('ST-202610-', LPAD(v_ticket_counter, 5, '0'));
    INSERT INTO customers (full_name, phone, created_at, updated_at) VALUES ('Đoàn Văn Hậu', '0912345678', NOW(), NOW());
    SET v_cust_id = LAST_INSERT_ID();
